MeasureStringX(UIFont.Small, "Confirm") + 8;
    local confirmButtonHeight = largeFontHeight;
    local confirmButtonX = paddingX;
    local confirmButtonY = speciesComboY + speciesComboHeight + paddingY;
    self.confirmButton = ISButton:new(confirmButtonX, confirmButtonY, confirmButtonWidth, confirmButtonHeight, "CONFIRM", self, FurrySpeciesSelectDialog.onConfirmed);
    self.confirmButton:initialise();
    self.confirmButton:instantiate();
    self:addChild(self.confirmButton);

    self:insertNewLineOfButtons(self.confirmButton);
    self:setHeight(confirmButtonY + confirmButtonHeight + paddingY);

    self.selectedSpecies = 'Hooman';
    self:updatePlayer('Hooman');
end

function FurrySpeciesSelectDialog:destroy()
    UIManager.setShowPausedMessage(true);
    self:setVisible(false);
    self:removeFromUIManager();
    if UIManager.getSpeedControls() then
        UIManager.getSpeedControls():SetCurrentGameSpeed(1);
    end
end

function FurrySpeciesSelectDialog:onConfirmed()
    -- Multiplayer
    if isClient() then
        FurryModClientNet.sendSpeciesToServer(self.player, self.selectedSpecies);

    -- Single-player
    else
        FurManager.changePlayerSpecies(self.player, self.selectedSpecies);
    end
    self:destroy();
end

function FurrySpeciesSelectDialog:updatePlayer(species)
    local newFurClothingName = FurManager.determineFurClothingName(self.player:isFemale(), species);
    FurManager.changePlayerFurClothing(self.player, newFurClothingName);
    self.selectedSpecies = species;
end

